import os,json,stat,subprocess,http.client
from pathlib import Path
root=Path('/srv/projects')
pairs={
'fadego/app.env':('/etc/fadego-staging/app.env','/srv/projects/fadego/private/systemd-env/app.env'),
'fadego/send-closed.env':('/etc/fadego-staging/send-closed.env','/srv/projects/fadego/private/systemd-env/send-closed.env'),
'pink-iptv/backend.env':('/etc/pink-iptv/backend.env','/srv/projects/pink-iptv/private/systemd-env/backend.env'),
'pink-iptv/secrets.env':('/etc/pink-iptv/secrets.env','/srv/projects/pink-iptv/private/systemd-env/secrets.env'),
'pink-iptv/vpn.env':('/etc/pink-iptv/vpn.env','/srv/projects/pink-iptv/private/systemd-env/vpn.env')
}
out={'files':{},'services':{},'http':{},'reviewed':{},'vault_present':False,'vault_timer':None,'canonical_repos':[],'metadata_only':True}
for k,(a,b) in pairs.items():
 p=Path(a);q=Path(b)
 row={'old_exists':p.is_file() and not p.is_symlink(),'private_exists':q.is_file() and not q.is_symlink()}
 if row['old_exists'] and row['private_exists']:
  row['same_bytes']=p.read_bytes()==q.read_bytes()
  row['old_owner']=p.stat().st_uid
  row['private_owner']=q.stat().st_uid
  row['old_mode']=oct(stat.S_IMODE(p.stat().st_mode))
  row['private_mode']=oct(stat.S_IMODE(q.stat().st_mode))
 out['files'][k]=row
for n in ('fadego-staging','pink-iptv-backend','pink-vpn','lowcost-europa','nginx','ssh','postgresql@16-main','pm2-iptvpn-bot','pm2-telegram-robot-leads'):
 p=subprocess.run(['systemctl','is-active',n],capture_output=True,text=True,timeout=8)
 out['services'][n]={'state':p.stdout.strip()}
 if n in ('fadego-staging','pink-iptv-backend'):
  q=subprocess.run(['systemctl','cat',n],capture_output=True,text=True,timeout=9)
  out['services'][n]['config_sources']=[z.strip() for z in q.stdout.splitlines() if z.strip().startswith('EnvironmentFile=')]
def status(port,path):
 try:
  c=http.client.HTTPConnection('127.0.0.1',port,timeout=7)
  c.request('GET',path,headers={'Host':'127.0.0.1'})
  z=c.getresponse().status;c.close();return z
 except Exception as e:return type(e).__name__
out['http']['fadego']=status(3100,'/')
out['http']['pink']=status(8010,'/')
p=Path('/etc/fadego-staging/reviewed')
if p.is_dir() and not p.is_symlink():
 out['reviewed']={'exists':True,'items':[{'name':x.name,'regular':x.is_file() and not x.is_symlink(),'bytes':x.stat().st_size if x.is_file() else None} for x in p.iterdir()]}
else:out['reviewed']={'exists':p.exists(),'kind':'link' if p.is_symlink() else 'other'}
out['vault_present']=Path('/root/project-secrets').is_dir()
out['vault_timer']=subprocess.run(['systemctl','is-active','project-secrets-offsite-backup.timer'],capture_output=True,text=True,timeout=8).stdout.strip()
out['canonical_repos']=sorted(p.name for p in root.iterdir() if p.is_dir() and not p.is_symlink())
print(json.dumps(out,separators=(',',':')))
